 * The result envelope every Server Action and Route Handler returns. Actions
 * never throw for expected failures — they return `ActionResult` so the client
 * form layer can render field errors without an error boundary.
 */

export type ErrorCode =
  | "unauthorized"
  | "forbidden"
  | "not_found"
  | "validation_failed"
  | "conflict"
  | "rate_limited"
  | "plan_limit_exceeded"
  | "tenant_scope_violation"
  | "internal_error";

export interface AppErrorShape {
  readonly code: ErrorCode;
  readonly message: string;
  /** Zod-style field path → messages, for react-hook-form to consume. */
  readonly fieldErrors?: Readonly<Record<string, readonly string[]>>;
  readonly meta?: Readonly<Record<string, string | number | boolean>>;
}

export type Result<T, E = AppErrorShape> =
  | { readonly ok: true; readonly data: T }
  | { readonly ok: false; readonly error: E };

/** What a Server Action returns to a `useActionState` reducer. */
export type ActionResult<T> = Result<T> & {
  /** Monotonic token so the client can distinguish two identical results. */
  readonly submittedAt?: string;
};

export interface ApiErrorBody {
  readonly error: AppErrorShape;
}

export function ok<T>(data: T): Result<T> {
  return { ok: true, data };
}

export function err<T = never>(error: AppErrorShape): Result<T> {
  return { ok: false, error };
}

export function isOk<T, E>(
  result: Result<T, E>,
): result is { ok: true; data: T } {
  return result.ok;
}
"use client";

/**
 * Due-date control that flags overdue values.
 */
import { DatePicker } from "@/components/ui/date-picker";
import { isOverdue, localDate, startOfLocalDate } from "@/lib/date";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import { toIsoTimestamp } from "@/types/common";
import type { IsoTimestamp } from "@/types/common";
import type { ReactElement } from "react";

export type IssueDueDateFieldProps = {
  value: IsoTimestamp | null;
  onChange: (value: IsoTimestamp | null) => void;
  timeZone?: string;
  status?: string;
};

/** The picker speaks `YYYY-MM-DD`; the domain stores full ISO timestamps. */
export function toDateInputValue(
  value: IsoTimestamp | null,
  timeZone = "UTC",
): string | null {
  return value === null ? null : localDate(value, timeZone);
}

export function fromDateInputValue(
  value: string | null,
  timeZone = "UTC",
): IsoTimestamp | null {
  if (value === null || value.length === 0) return null;
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value);
  if (!match) throw new RangeError(`Malformed local date: "${value}"`);
  const [year, month, day] = match.slice(1).map(Number);
  const nextDate = new Date(Date.UTC(year!, month! - 1, day! + 1));
  const nextMidnight = startOfLocalDate(
    `${String(nextDate.getUTCFullYear()).padStart(4, "0")}-${String(nextDate.getUTCMonth() + 1).padStart(2, "0")}-${String(nextDate.getUTCDate()).padStart(2, "0")}`,
    timeZone,
  );
  // Store the last instant of the selected workspace-local day.
  return toIsoTimestamp(new Date(new Date(nextMidnight).getTime() - 1));
}

export function IssueDueDateField(
  props: IssueDueDateFieldProps,
): ReactElement | null {
  const timeZone = props.timeZone ?? "UTC";
  const overdue =
    !CLOSED_ISSUE_STATUSES.includes(props.status as "done" | "canceled") &&
    isOverdue(props.value, new Date(), timeZone);

  return (
    <div className="space-y-1">
      <DatePicker
        value={toDateInputValue(props.value, timeZone)}
        placeholder="No due date"
        onChange={(value) => props.onChange(fromDateInputValue(value, timeZone))}
      />
      {overdue ? (
        <p className="text-xs text-red-600">This issue is past its due date.</p>
      ) : null}
    </div>
  );
}

