/**
 * Timestamp helpers: ISO round-tripping, relative formatting, due-date and
 * digest-window arithmetic.
 *
 * Every timestamp in Taskflow is an `IsoTimestamp` (a UTC ISO-8601 string in
 * a SQLite text column). Nothing outside this module constructs a `Date` from
 * a stored value — going through `parseIso()` keeps the "what if it is
 * malformed" answer in one place.
 */
import type { IsoTimestamp } from "@/types/common";
import { toIsoTimestamp } from "@/types/common";

const MINUTE_MS = 60_000;
const HOUR_MS = 60 * MINUTE_MS;
const DAY_MS = 24 * HOUR_MS;
const WEEK_MS = 7 * DAY_MS;

type ZonedParts = {
  year: number;
  month: number;
  day: number;
  hour: number;
  minute: number;
  second: number;
};

const zonedFormatters = new Map<string, Intl.DateTimeFormat>();

function formatterFor(timeZone: string): Intl.DateTimeFormat {
  let formatter = zonedFormatters.get(timeZone);
  if (formatter === undefined) {
    formatter = new Intl.DateTimeFormat("en-CA", {
      timeZone,
      calendar: "gregory",
      numberingSystem: "latn",
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
      hour: "2-digit",
      minute: "2-digit",
      second: "2-digit",
      hourCycle: "h23",
    });
    zonedFormatters.set(timeZone, formatter);
  }
  return formatter;
}

function zonedParts(date: Date, timeZone: string): ZonedParts {
  const parts = formatterFor(timeZone).formatToParts(date);
  const values: Record<string, number> = {};
  for (const part of parts) {
    if (part.type !== "literal") values[part.type] = Number(part.value);
  }
  return {
    year: values.year ?? 0,
    month: values.month ?? 0,
    day: values.day ?? 0,
    hour: values.hour ?? 0,
    minute: values.minute ?? 0,
    second: values.second ?? 0,
  };
}

function dateString(parts: Pick<ZonedParts, "year" | "month" | "day">): string {
  return `${String(parts.year).padStart(4, "0")}-${String(parts.month).padStart(2, "0")}-${String(parts.day).padStart(2, "0")}`;
}

function dateStringAt(date: Date, timeZone: string): string {
  return dateString(zonedParts(date, timeZone));
}

function shiftCalendarDate(value: string, days: number): string {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value);
  if (!match) throw new RangeError(`Malformed local date: "${value}"`);
  const date = new Date(
    Date.UTC(Number(match[1]), Number(match[2]) - 1, Number(match[3]) + days),
  );
  return `${String(date.getUTCFullYear()).padStart(4, "0")}-${String(date.getUTCMonth() + 1).padStart(2, "0")}-${String(date.getUTCDate()).padStart(2, "0")}`;
}

/** Throws RangeError when Intl does not recognise the supplied IANA zone. */
export function assertValidTimeZone(timeZone: string): void {
  formatterFor(timeZone);
}

function startOfDate(date: string, timeZone: string, approximate: number): Date {
  assertValidTimeZone(timeZone);
  let lower = approximate;
  let upper = approximate;
  let lowerDate = dateStringAt(new Date(lower), timeZone);
  let upperDate = lowerDate;
  let step = 6 * HOUR_MS;

  if (lowerDate < date) {
    while (upperDate < date) {
      lower = upper;
      upper += step;
      upperDate = dateStringAt(new Date(upper), timeZone);
      step *= 2;
    }
  } else {
    while (lowerDate >= date) {
      upper = lower;
      lower -= step;
      lowerDate = dateStringAt(new Date(lower), timeZone);
      step *= 2;
    }
  }

  // The local date changes monotonically across an ordinary calendar-day
  // boundary. Binary search gives the first millisecond belonging to `date`,
  // including zones where midnight itself is skipped by a clock change.
  while (upper - lower > 1) {
    const middle = Math.floor((lower + upper) / 2);
    if (dateStringAt(new Date(middle), timeZone) >= date) upper = middle;
    else lower = middle;
  }
  return new Date(upper);
}

function localDateTimeCandidates(
  date: string,
  hour: number,
  timeZone: string,
): Date[] {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(date);
  if (!match) throw new RangeError(`Malformed local date: "${date}"`);
  const [year, month, day] = match.slice(1).map(Number);
  const wallTime = Date.UTC(year!, month! - 1, day!, hour, 0, 0, 0);
  const offsets = new Set<number>();

  // Sample both sides of possible offset changes so repeated wall-clock
  // hours produce both of their corresponding UTC instants.
  for (let offset = -36; offset <= 36; offset += 6) {
    const sample = new Date(wallTime + offset * HOUR_MS);
    const local = zonedParts(sample, timeZone);
    const localAsUtc = Date.UTC(
      local.year,
      local.month - 1,
      local.day,
      local.hour,
      local.minute,
      local.second,
    );
    offsets.add(localAsUtc - Math.floor(sample.getTime() / 1000) * 1000);
  }

  const exact = [...offsets]
    .map((offset) => new Date(wallTime - offset))
    .filter((candidate) => {
      const parts = zonedParts(candidate, timeZone);
      return (
        dateString(parts) === date &&
        parts.hour === hour &&
        parts.minute === 0 &&
        parts.second === 0
      );
    })
    .sort((a, b) => a.getTime() - b.getTime());

  if (exact.length > 0) return exact;

  // If a DST jump removes the configured wall hour, use the next existing
  // whole-hour boundary on that calendar date.
  for (let nextHour = hour + 1; nextHour < 24; nextHour += 1) {
    const later = localDateTimeCandidatesExact(date, nextHour, timeZone, offsets);
    if (later.length > 0) return later;
  }
  return [startOfDate(date, timeZone, wallTime)];
}

function localDateTimeCandidatesExact(
  date: string,
  hour: number,
  timeZone: string,
  knownOffsets: ReadonlySet<number>,
): Date[] {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(date);
  if (!match) throw new RangeError(`Malformed local date: "${date}"`);
  const [year, month, day] = match.slice(1).map(Number);
  const wallTime = Date.UTC(year!, month! - 1, day!, hour, 0, 0, 0);
  return [...knownOffsets]
    .map((offset) => new Date(wallTime - offset))
    .filter((candidate) => {
      const parts = zonedParts(candidate, timeZone);
      return (
        dateString(parts) === date &&
        parts.hour === hour &&
        parts.minute === 0 &&
        parts.second === 0
      );
    })
    .sort((a, b) => a.getTime() - b.getTime());
}

export function now(): IsoTimestamp {
  return toIsoTimestamp(new Date());
}

/** Parses a stored timestamp; throws rather than yielding an Invalid Date. */
export function parseIso(value: IsoTimestamp): Date {
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) {
    throw new RangeError(`Malformed IsoTimestamp: "${value}"`);
  }
  return date;
}

function plural(count: number, unit: string): string {
  return `${count} ${unit}${count === 1 ? "" : "s"}`;
}

/**
 * "just now" / "5 minutes ago" / "in 2 days" — the wording the activity feed,
 * issue cards and comment headers all use.
 */
export function formatRelative(
  value: IsoTimestamp,
  reference: Date = new Date(),
): string {
  const deltaMs = parseIso(value).getTime() - reference.getTime();
  const past = deltaMs < 0;
  const abs = Math.abs(deltaMs);

  const phrase = ((): string => {
    if (abs < MINUTE_MS) return "just now";
    if (abs < HOUR_MS) return plural(Math.floor(abs / MINUTE_MS), "minute");
    if (abs < DAY_MS) return plural(Math.floor(abs / HOUR_MS), "hour");
    if (abs < WEEK_MS) return plural(Math.floor(abs / DAY_MS), "day");
    if (abs < 30 * DAY_MS) return plural(Math.floor(abs / WEEK_MS), "week");
    if (abs < 365 * DAY_MS) return plural(Math.floor(abs / (30 * DAY_MS)), "month");
    return plural(Math.floor(abs / (365 * DAY_MS)), "year");
  })();

  if (phrase === "just now") return phrase;
  return past ? `${phrase} ago` : `in ${phrase}`;
}

/** Absolute calendar rendering, e.g. "12 Mar 2026", in the given timezone. */
export function formatDate(value: IsoTimestamp, timezone = "UTC"): string {
  return new Intl.DateTimeFormat("en-GB", {
    day: "2-digit",
    month: "short",
    year: "numeric",
    timeZone: timezone,
  }).format(parseIso(value));
}

/** The local YYYY-MM-DD calendar date containing an instant. */
export function localDate(value: IsoTimestamp, timeZone: string): string {
  return dateString(zonedParts(parseIso(value), timeZone));
}

/** UTC instant at which the workspace's current local calendar day began. */
export function startOfLocalDay(
  reference: Date,
  timeZone: string,
): IsoTimestamp {
  const date = dateStringAt(reference, timeZone);
  return toIsoTimestamp(startOfDate(date, timeZone, reference.getTime()));
}

/** UTC instant at which a specified workspace-local calendar date began. */
export function startOfLocalDate(
  date: string,
  timeZone: string,
): IsoTimestamp {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(date);
  if (!match) throw new RangeError(`Malformed local date: "${date}"`);
  const [year, month, day] = match.slice(1).map(Number);
  const approximate = Date.UTC(year!, month! - 1, day!, 12);
  return toIsoTimestamp(startOfDate(date, timeZone, approximate));
}

/** True when a due date's workspace-local calendar day has ended. */
export function isOverdue(
  dueAt: IsoTimestamp | null,
  reference: Date = new Date(),
  timeZone = "UTC",
): boolean {
  if (dueAt === null) return false;
  return localDate(dueAt, timeZone) < localDate(toIsoTimestamp(reference), timeZone);
}

export function addDays(value: IsoTimestamp, days: number): IsoTimestamp {
  return toIsoTimestamp(new Date(parseIso(value).getTime() + days * DAY_MS));
}

/**
 * The local calendar-day window ending at the most recent workspace-local
 * `digestHourUtc`. Its elapsed duration is 23 or 25 hours across DST changes.
 */
export function digestWindow(
  digestHourUtc: number,
  reference: Date,
  timeZone = "UTC",
): { start: IsoTimestamp; end: IsoTimestamp } {
  if (!Number.isInteger(digestHourUtc) || digestHourUtc < 0 || digestHourUtc > 23) {
    throw new RangeError(`digestHourUtc must be 0-23, got ${digestHourUtc}`);
  }

  const current = zonedParts(reference, timeZone);
  const today = dateString(current);
  const endDate = current.hour < digestHourUtc
    ? shiftCalendarDate(today, -1)
    : today;
  const endCandidates = localDateTimeCandidates(endDate, digestHourUtc, timeZone);
  const end = endCandidates
    .filter((candidate) => candidate.getTime() <= reference.getTime())
    .at(-1) ?? endCandidates[0]!;
  const startDate = shiftCalendarDate(endDate, -1);
  const start = localDateTimeCandidates(startDate, digestHourUtc, timeZone)[0]!;

  return {
    start: toIsoTimestamp(start),
    end: toIsoTimestamp(end),
  };
}
/**
 * Builds and 'sends' the daily digest for every subscriber of every org whose digest hour has arrived.
 *
 * Must call (do not reimplement): isEnabled, buildDigest, sendEmail
 */
import { isEnabled } from "@/lib/feature-flags";
import { digestWindow } from "@/lib/date";
import { createLogger } from "@/lib/logger";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as userRepo from "@/server/repositories/user-repository";
import { buildDigest, listDigestRecipients, renderDigest } from "@/server/services/digest-service";
import { sendEmail } from "@/server/services/email-service";
import { buildFlagContext } from "@/server/services/feature-flag-service";
import { toIsoTimestamp } from "@/types/common";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { Organization } from "@/types/organization";

const ORG_BATCH = 50;
const logger = createLogger("digest-email-job");

/**
 * One pass per scheduler tick. Each org is only processed during the local hour
 * it configured, so a tick that runs every few minutes still sends exactly one
 * digest per day per recipient.
 */
export async function runDigestEmailJob(now: Date): Promise<JobResult> {
  return runJob("digest-email", async (result) => {
    const orgIds = await usageRepo.listOrgIdsForRollup(ORG_BATCH);

    for (const orgId of orgIds) {
      const org = await orgRepo.findOrgById(orgId);
      if (!org || !shouldRunForOrg(org, now)) continue;

      if (!isEnabled("digest_email", buildFlagContext(null, org))) continue;

      const window = digestWindow(
        org.settings.digestHourUtc,
        now,
        org.settings.timeZone,
      );
      const { start: windowStart, end: windowEnd } = window;

      for (const recipientId of await listDigestRecipients(orgId)) {
        try {
          const bundle = await buildDigest(
            orgId,
            recipientId,
            windowStart,
            windowEnd,
          );
          if (!bundle) continue;

          const recipient = await userRepo.findUserById(recipientId);
          if (!recipient) continue;

          const rendered = await renderDigest(bundle, recipient);
          await sendEmail({ to: recipient.email, ...rendered });

          // Once digested, these notifications are no longer "unread" — this
          // is what keeps a later run inside the same window from sending
          // the same digest twice.
          for (const entry of bundle.entries) {
            await notificationRepo.markRead(orgId, entry.notificationId, windowEnd);
          }

          result.processed += 1;
        } catch (error) {
          result.failed += 1;
          logger.error("digest failed", {
            orgId,
            recipientId,
            reason: error instanceof Error ? error.message : String(error),
          });
        }
      }
    }
  });
}

/**
 * True during the org's configured digest hour. Exported because the schedule
 * decision is worth testing on its own, without a database.
 */
export function shouldRunForOrg(org: Organization, now: Date): boolean {
  if (org.archivedAt !== null) return false;
  const hour = Number(
    new Intl.DateTimeFormat("en-US", {
      timeZone: org.settings.timeZone,
      hour: "2-digit",
      hourCycle: "h23",
    })
      .formatToParts(now)
      .find((part) => part.type === "hour")?.value,
  );
  return hour === org.settings.digestHourUtc;
}
